function Get-IisPrerequisiteState {
    <# .SYNOPSIS Read-only detection of IIS role, URL Rewrite and ARR. Generated Nov-01-2026. #>
    $iis = Test-Path 'HKLM:\SOFTWARE\Microsoft\InetStp'
    $rewrite = Test-Path 'HKLM:\SOFTWARE\Microsoft\IIS Extensions\URL Rewrite'
    $arr = Test-Path 'HKLM:\SOFTWARE\Microsoft\IIS Extensions\Application Request Routing'
    $module = [bool](Get-Module -ListAvailable -Name WebAdministration)
    return [pscustomobject]@{ IisInstalled = $iis; UrlRewrite = $rewrite; Arr = $arr; WebAdministration = $module }
}

function Install-IisFeatures {
    <# .SYNOPSIS After approval, installs the minimal IIS role and scripting tools (Server or client SKU). Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param()
    if (-not (Request-Approval -Action 'Install IIS role features' -Target 'Windows features' -Detail 'Web-Server, static content, HTTP errors, request filtering, logging, scripting tools. May require a reboot.')) { return $false }
    if (Get-Command Install-WindowsFeature -ErrorAction SilentlyContinue) {
        Install-WindowsFeature -Name Web-Server, Web-Static-Content, Web-Http-Errors, Web-Filtering, Web-Http-Logging, Web-Scripting-Tools | Out-Null
    } else {
        foreach ($f in 'IIS-WebServerRole', 'IIS-WebServer', 'IIS-StaticContent', 'IIS-HttpErrors', 'IIS-RequestFiltering', 'IIS-HttpLogging', 'IIS-ManagementScriptingTools') {
            Enable-WindowsOptionalFeature -Online -FeatureName $f -All -NoRestart | Out-Null
        }
    }
    return $true
}

