    if (-not (Request-Approval -Action "Install $($item.Title)" -Target 'IIS (server-wide module)' -Detail "Downloads $($item.Url); Microsoft publishes no checksum, so the Microsoft Authenticode signature is enforced; runs msiexec silently.")) { return $false }
