function Get-CloudflareCaFiles {
    <# .SYNOPSIS Verifies bundled public Origin CA files against official-download SHA-256 pins; never imports them into Windows trust stores. #>
    param([Parameter(Mandatory)][string]$ScriptRoot)
    $pins = @{
        'origin_ca_rsa_root.crt' = '91A8A5567EFA6BF941162AA806B3BA476AADDF7867640E53053B35FB225A5DAE'
        'origin_ca_ecc_root.crt' = 'CA56C5B29918FAF79046B1C1726C35D7715951A35445B2E63F56EA5A70B7AF9C'
        'origin_ca_bundle.crt' = '01D12A7C938DE82B3B264458A24DD2CDA139814393A920D8B5B9D0AA6A54D8F3'
    }
    $paths = @{}
    foreach ($name in $pins.Keys) {
        $path = Join-Path $ScriptRoot "certificates\$name"
        if ((Get-FileHash -LiteralPath $path -Algorithm SHA256 -ErrorAction Stop).Hash -ne $pins[$name]) {
            throw "Cloudflare Origin CA file integrity check failed: $name"
        }
        $paths[$name] = $path
    }
    return $paths
}

function Test-HttpsCertificate {
    <# .SYNOPSIS Returns certificate problems; checks private key, validity, DNS, server-auth chain and public trust or an explicitly pinned Origin CA. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][Security.Cryptography.X509Certificates.X509Certificate2]$Certificate,
        [Parameter(Mandatory)][string]$Domain, [switch]$CloudflareProxy, [string]$ScriptRoot = (Split-Path $PSScriptRoot))
    $problems = @()
    if (-not $Certificate.HasPrivateKey) { $problems += 'no private key' }
    if ($Certificate.NotAfter -le (Get-Date) -or $Certificate.NotBefore -gt (Get-Date)) { $problems += 'not currently valid' }
    if ($Certificate.Subject -eq $Certificate.Issuer) { $problems += 'self-signed certificates are not allowed in production' }
    $chain = New-Object Security.Cryptography.X509Certificates.X509Chain
    $roots = @()
    try {
        $null = $chain.ChainPolicy.ApplicationPolicy.Add((New-Object Security.Cryptography.Oid '1.3.6.1.5.5.7.3.1'))
        if ($CloudflareProxy) {
            $files = Get-CloudflareCaFiles -ScriptRoot $ScriptRoot
            $roots = @('origin_ca_rsa_root.crt', 'origin_ca_ecc_root.crt' | ForEach-Object {
                New-Object Security.Cryptography.X509Certificates.X509Certificate2 $files[$_]
            })
            foreach ($root in $roots) { $null = $chain.ChainPolicy.ExtraStore.Add($root) }
            $chain.ChainPolicy.VerificationFlags = [Security.Cryptography.X509Certificates.X509VerificationFlags]::AllowUnknownCertificateAuthority
            # Origin CA does not publish a Windows CRL/OCSP endpoint; Cloudflare Full (strict) is required.
            $chain.ChainPolicy.RevocationMode = [Security.Cryptography.X509Certificates.X509RevocationMode]::NoCheck
        }
        $valid = $chain.Build($Certificate)
        if (-not $valid) { $problems += 'chain does not validate: ' + (($chain.ChainStatus | ForEach-Object { $_.StatusInformation.Trim() }) -join '; ') }
        if ($CloudflareProxy) {
            $anchor = $chain.ChainElements[$chain.ChainElements.Count - 1].Certificate
            if ($anchor.Thumbprint -notin @($roots | ForEach-Object { $_.Thumbprint })) {
                $problems += 'certificate is not signed by a pinned Cloudflare Origin CA'
            }
            $unexpected = @($chain.ChainStatus | Where-Object {
                $_.Status -ne [Security.Cryptography.X509Certificates.X509ChainStatusFlags]::UntrustedRoot
            })
            if ($unexpected.Count) { $problems += 'Origin certificate has unexpected chain errors' }
        }
    } finally {
        $chain.Dispose()
        foreach ($root in $roots) { $root.Dispose() }
    }
    $names = @($Certificate.DnsNameList | ForEach-Object { $_.Unicode })
    $match = $names | Where-Object {
        $_ -ieq $Domain -or ($_.StartsWith('*.') -and $Domain.Split('.').Count -eq $_.Split('.').Count -and $Domain.EndsWith($_.Substring(1), [StringComparison]::OrdinalIgnoreCase))
    }
    if (-not $match) { $problems += "does not cover $Domain" }
    return $problems
}

function Select-HttpsCertificate {
    <# .SYNOPSIS Picks an existing LocalMachine\My certificate (by thumbprint or interactive choice) or imports a PFX with a secure password prompt; rejects unsuitable certificates. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    $store = 'Cert:\LocalMachine\My'
    $candidates = @(Get-ChildItem $store | Where-Object { (Test-HttpsCertificate -Certificate $_ -Domain $Config.Domain -CloudflareProxy:$Config.CloudflareProxy -ScriptRoot $Config.ScriptRoot).Count -eq 0 })
    if ($Config.CertificateThumbprint) {
        $c = $candidates | Where-Object Thumbprint -eq ($Config.CertificateThumbprint -replace '\s', '').ToUpperInvariant()
        if (-not $c) { throw "Thumbprint $($Config.CertificateThumbprint) is not a valid certificate for $($Config.Domain) in $store." }
        return $c
    }
    if ($Config.PfxPath) {
        if (-not (Request-Approval -Action 'Import PFX certificate' -Target $store -Detail "PFX: $($Config.PfxPath). You will be asked for its password." -Required)) { return $null }
        $imported = Import-PfxCertificate -FilePath $Config.PfxPath -CertStoreLocation $store -Password (Read-SecretPrompt -Prompt 'PFX password' -EnvironmentVariable 'GARAGE_PFX_PASSWORD')
        $bad = Test-HttpsCertificate -Certificate $imported -Domain $Config.Domain -CloudflareProxy:$Config.CloudflareProxy -ScriptRoot $Config.ScriptRoot
        if ($bad) { throw "Imported certificate rejected: $($bad -join '; ')" }
        return $imported
    }
    if (-not $candidates) { throw "No valid, CA-issued certificate for $($Config.Domain) in $store. Provide -PfxPath or install one; self-signed production certificates are refused." }
    if ($candidates.Count -eq 1 -and -not (Test-InteractiveSession)) { return $candidates[0] }
    $i = 0
    $candidates | ForEach-Object { Write-Host ("   [{0}] {1}  expires {2:yyyy-MM-dd}  {3}" -f $i++, $_.Thumbprint, $_.NotAfter, $_.Subject) }
    $answer = Read-Host 'Select certificate number'
    if ($answer -notmatch '^\d+$' -or [int]$answer -ge $candidates.Count) { throw 'Invalid certificate selection.' }
    return $candidates[[int]$answer]
}

function Assert-NoIisConflicts {
    <# .SYNOPSIS Throws if another site already binds the domain or owns the physical path, or if a non-SNI 0.0.0.0:443 certificate binding would clash. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    Import-Module WebAdministration
    foreach ($site in Get-Website) {
        if ($site.Name -ieq $Config.SiteName) { continue }
        foreach ($b in $site.Bindings.Collection) {
            if ($b.bindingInformation -match [regex]::Escape(":$($Config.Domain)") + '$') { throw "Binding conflict: site '$($site.Name)' already binds $($b.bindingInformation)." }
        }
        if ($site.PhysicalPath -and ([Environment]::ExpandEnvironmentVariables($site.PhysicalPath)).TrimEnd('\') -ieq $Config.IisRoot.TrimEnd('\')) { throw "Site '$($site.Name)' already uses $($Config.IisRoot)." }
    }
    $nonSni = Get-ChildItem IIS:\SslBindings -ErrorAction SilentlyContinue | Where-Object { $_.Port -eq 443 -and -not $_.Host -and $_.IPAddress.ToString() -in @('0.0.0.0', '::') -and $_.Sites -and ($_.Sites.Value -notcontains $Config.SiteName) }
    if ($nonSni) { throw 'An existing non-SNI certificate binding owns 0.0.0.0:443; it would conflict with an SNI binding. Resolve in IIS first (no changes were made).' }
}

function Get-IisWebConfigText {
    <# .SYNOPSIS Returns iis\web.config adapted to the configured domain and loopback port. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $text = Get-Content -LiteralPath (Join-Path $Config.ScriptRoot 'iis\web.config') -Raw
    $text = $text.Replace('android\.sgsoftech\.in', [regex]::Escape($Config.Domain)).Replace('android.sgsoftech.in', $Config.Domain)
    return $text.Replace('http://127.0.0.1:3000/', "http://127.0.0.1:$($Config.ApiPort)/")
}

function Set-GarageIisSite {
    <# .SYNOPSIS After approval, creates/validates the dedicated app pool, site, bindings, certificate, web.config and ARR proxy flag without touching other sites. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    Import-Module WebAdministration
    Assert-NoIisConflicts -Config $Config
    $cert = Select-HttpsCertificate -Config $Config
    if (-not $cert) { return }
    $detail = "Pool $($Config.AppPoolName), site $($Config.SiteName) at $($Config.IisRoot), bindings http/https $($Config.Domain), cert $($cert.Thumbprint). Enabling ARR proxy is SERVER-WIDE."
    if (-not (Request-Approval -Action 'Create/update IIS reverse-proxy site' -Target $Config.Domain -Detail $detail -Required)) { return }
    New-Item -ItemType Directory -Force -Path $Config.IisRoot | Out-Null
    $webConfigPath = Join-Path $Config.IisRoot 'web.config'
    $newWebConfig = Get-IisWebConfigText -Config $Config
    if ((Test-Path -LiteralPath $webConfigPath) -and ((Get-Content -LiteralPath $webConfigPath -Raw) -ne $newWebConfig)) {
        Copy-Item -LiteralPath $webConfigPath -Destination "$webConfigPath.bak-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
    }
    [IO.File]::WriteAllText($webConfigPath, $newWebConfig, (New-Object Text.UTF8Encoding $false))
    $poolPath = "IIS:\AppPools\$($Config.AppPoolName)"
    if (-not (Test-Path $poolPath)) {
        New-WebAppPool -Name $Config.AppPoolName | Out-Null
        Set-ItemProperty $poolPath -Name managedRuntimeVersion -Value ''
        Set-ItemProperty $poolPath -Name managedPipelineMode -Value 'Integrated'
    } else {
        $others = @(Get-Website | Where-Object { $_.Name -ne $Config.SiteName -and $_.ApplicationPool -ieq $Config.AppPoolName })
        if ($others) { throw "Application pool $($Config.AppPoolName) is shared with site(s) $($others.Name -join ', '); refusing to reuse it." }
        Write-Info "Reusing existing pool $($Config.AppPoolName); its settings are left unchanged."
    }
    Invoke-Native -FilePath 'icacls.exe' -Arguments @($Config.IisRoot, '/grant', "IIS AppPool\$($Config.AppPoolName):(OI)(CI)RX") | Out-Null
    $site = Get-Website | Where-Object Name -eq $Config.SiteName
    if (-not $site) { New-Website -Name $Config.SiteName -PhysicalPath $Config.IisRoot -ApplicationPool $Config.AppPoolName -HostHeader $Config.Domain -Port 80 -IPAddress '*' | Out-Null }
    elseif (([Environment]::ExpandEnvironmentVariables($site.PhysicalPath)).TrimEnd('\') -ine $Config.IisRoot.TrimEnd('\')) { throw "Existing site $($Config.SiteName) uses a different physical path." }
    if (-not (Get-WebBinding -Name $Config.SiteName -Protocol http -HostHeader $Config.Domain -Port 80)) {
        New-WebBinding -Name $Config.SiteName -Protocol http -Port 80 -IPAddress '*' -HostHeader $Config.Domain
    }
    $https = Get-WebBinding -Name $Config.SiteName -Protocol https -HostHeader $Config.Domain -Port 443
    if (-not $https) {
        New-WebBinding -Name $Config.SiteName -Protocol https -Port 443 -IPAddress '*' -HostHeader $Config.Domain -SslFlags 1
        $https = Get-WebBinding -Name $Config.SiteName -Protocol https -HostHeader $Config.Domain -Port 443
    }
    if ($https.certificateHash -and $https.certificateHash -ne $cert.Thumbprint) {
        throw "HTTPS binding already uses certificate $($https.certificateHash), not $($cert.Thumbprint); existing bindings are preserved. Change it deliberately in IIS Manager."
    }
    if (-not $https.certificateHash) { $https.AddSslCertificate($cert.Thumbprint, 'My') }
    $proxy = 'MACHINE/WEBROOT/APPHOST'
    if (-not (Get-WebConfigurationProperty -PSPath $proxy -Filter 'system.webServer/proxy' -Name enabled).Value) {
        if (Request-Approval -Action 'Enable ARR proxy (SERVER-WIDE IIS setting)' -Target 'MACHINE/WEBROOT/APPHOST system.webServer/proxy' -Detail 'This changes IIS globally and affects every site that has proxy rewrite rules. Decline to configure it yourself in IIS Manager; the final HTTPS check will then fail.' -Required) {
            Set-WebConfigurationProperty -PSPath $proxy -Filter 'system.webServer/proxy' -Name enabled -Value $true
        }
    }
    Start-Website -Name $Config.SiteName -ErrorAction SilentlyContinue
}

function Test-PublicHttps {
    <# .SYNOPSIS Verifies local SNI HTTPS with system/pinned origin trust, then public HTTPS with system trust and Cloudflare proxy evidence when requested. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $url = "https://$($Config.Domain)/health"
    $originTls = @()
    if ($Config.CloudflareProxy) {
        $files = Get-CloudflareCaFiles -ScriptRoot $Config.ScriptRoot
        $originTls = @('--cacert', $files['origin_ca_bundle.crt'])
        Write-Info 'Cloudflare mode requires Proxied DNS and Full (strict). Keep API caching disabled and restrict origin inbound access to Cloudflare where possible.'
    }
    $local = Invoke-Native -FilePath 'curl.exe' -Arguments (@('--silent', '--show-error', '--max-time', '20', '--resolve', "$($Config.Domain):443:127.0.0.1") + $originTls + @($url)) -AllowFailure
    if ($local.ExitCode -ne 0 -or ($local.Output -join '') -notmatch '"status"\s*:\s*"ok"') {
        throw "HTTPS via the local binding FAILED (curl exit $($local.ExitCode)): $($local.Output -join ' '). Check certificate, ARR proxy, URL Rewrite and the service."
    }
    Write-Info 'HTTPS via local IIS binding: ok (hostname and certificate chain validated by curl).'
    $public = Invoke-Native -FilePath 'curl.exe' -Arguments @('--silent', '--show-error', '--max-time', '20', '--dump-header', '-', $url) -AllowFailure
    if ($public.ExitCode -ne 0 -or ($public.Output -join '') -notmatch '"status"\s*:\s*"ok"') {
        throw "EXTERNAL HTTPS check FAILED (curl exit $($public.ExitCode)): $($public.Output -join ' '). This is outside script control: verify the public DNS A/AAAA record, firewall/NAT for 443 and that the certificate chain is public-trusted. Test again from a separate network."
    }
    if ($Config.CloudflareProxy -and ($public.Output -join "`n") -notmatch '(?im)^cf-ray:\s*\S+') {
        throw 'Public HTTPS did not return Cloudflare CF-Ray. Verify orange-cloud DNS proxying and do not use a DNS-only Origin certificate.'
    }
    Write-Info 'HTTPS via public DNS: ok.'
    $auth = Invoke-Native -FilePath 'curl.exe' -Arguments @('--silent', '--output', 'NUL', '--write-out', '%{http_code}', '--max-time', '20', "https://$($Config.Domain)/customers") -AllowFailure
    if ($auth.ExitCode -ne 0 -or ($auth.Output -join '') -ne '400') {
        throw "Unregistered /customers returned '$($auth.Output -join '')' (curl exit $($auth.ExitCode)) instead of 400 for missing installation credentials."
    }
}
